        return urlsplit(self.path).path

    def _body(self) -> dict[str, Any]:
        if self.headers.get("Transfer-Encoding") is not None:
            raise RequestError(400, "transfer encoding is not supported")
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            raise RequestError(411, "Content-Length is required")
        try:
            length = int(raw_length)
        except ValueError as exc:
            raise RequestError(400, "invalid Content-Length") from exc
        if length < 0:
            raise RequestError(400, "invalid Content-Length")
        if length > MAX_BODY:
            # Consume at most one byte beyond the limit.  This drains the
            # common MAX_BODY + 1 case so the peer receives the JSON 413
            # response instead of a TCP reset, while still bounding the work
            # an attacker can cause with an enormous Content-Length.
            self.rfile.read(MAX_BODY + 1)
            self.close_connection = True
            raise RequestError(413, "request body exceeds 1 MiB")
        body = self.rfile.read(length)
        try:
            value = json.loads(body.decode("utf-8"), parse_constant=Store._invalid_constant)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            raise RequestError(400, "malformed JSON") from exc
        if not isinstance(value, dict):
            raise RequestError(400, "request body must be a JSON object")
        return value

    def _dispatch(self) -> None:
        path = self._path()
        if path == "/health":
            if self.command == "GET":
                self._json(200, {"status": "ok"})
            else:
                self._error(405, "method not allowed")
            return
        if path == "/v1/keys":
            if self.command == "GET":
                self._json(200, {"keys": self.store.keys()})
            else:
                self._error(405, "method not allowed")
            return
        key = self._key(path)
        if key is None:
            self._error(404, "route not found")
            return
        if self.command == "GET":
            found, value = self.store.get(key)
            if found:
                self._json(200, {"key": key, "value": value})
            else:
                self._error(404, "key not found")
            return
        if self.command == "DELETE":
            if self.store.delete(key):
                self._empty(204)
            else:
                self._error(404, "key not found")
            return
        if self.command == "PUT":
            body = self._body()
            if "value" not in body or set(body) - {"value", "ttl_seconds"}:
                raise RequestError(400, "body must contain value and optional ttl_seconds")
            ttl = body.get("ttl_seconds")
            if ttl is not None:
                if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0:
                    raise RequestError(400, "ttl_seconds must be a finite number greater than zero")
                ttl = float(ttl)
            created = self.store.put(key, body["value"], ttl)
            self._json(201 if created else 200, {"key": key, "value": body["value"]})
            return
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON HTTP service with TTL support and atomic
on-disk persistence.

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Use port `0` to select a free port. The service prints `LISTENING <port>` as
its first stdout line; request diagnostics go to stderr.

## API

- `PUT /v1/kv/{url-encoded-key}` — JSON body `{"value": ..., "ttl_seconds": 60}`;
  the TTL is optional. Returns 201 when created and 200 when replaced.
- `GET /v1/kv/{url-encoded-key}` — returns the key and value.
- `DELETE /v1/kv/{url-encoded-key}` — returns 204 when deleted.
- `GET /v1/keys` — returns live keys in lexicographic order.
- `GET /health` — returns `{"status":"ok"}`.

All normal and error payloads are JSON. Request bodies are limited to 1 MiB.
State-changing requests are serialized, and each successful mutation is
committed by atomically replacing the data file. SIGINT and SIGTERM trigger a
clean shutdown.
